package com.cohenadair.anglerslog.model.user_defines;

import android.content.ContentValues;
import android.content.Context;
import android.content.Intent;
import android.text.format.DateFormat;

import com.cohenadair.anglerslog.R;
import com.cohenadair.anglerslog.database.QueryHelper;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.backup.Json;
import com.cohenadair.anglerslog.model.backup.JsonExporter;
import com.cohenadair.anglerslog.model.backup.JsonImporter;
import com.cohenadair.anglerslog.model.utilities.HasCatchesInterface;
import com.cohenadair.anglerslog.model.utilities.HasDateInterface;
import com.cohenadair.anglerslog.model.utilities.UsedUserDefineObject;
import com.cohenadair.anglerslog.model.utilities.UserDefineArrays;
import com.cohenadair.anglerslog.utilities.Utils;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.Date;
import java.util.UUID;

import static com.cohenadair.anglerslog.database.LogbookSchema.TripTable;
import static com.cohenadair.anglerslog.database.LogbookSchema.UsedAnglerTable;
import static com.cohenadair.anglerslog.database.LogbookSchema.UsedCatchTable;
import static com.cohenadair.anglerslog.database.LogbookSchema.UsedLocationTable;

/**
 * The Trip class manages all data associated with a single trip. A trip is added (optionally) by
 * the user.
 *
 * @author Cohen Adair
 */
public class Trip extends UserDefineObject implements HasCatchesInterface, HasDateInterface {

    private Date mStartDate;
    private Date mEndDate;
    private String mNotes;

    // utility objects for database interaction
    private UsedUserDefineObject mUsedAnglers;
    private UsedUserDefineObject mUsedLocations;
    private UsedUserDefineObject mUsedCatches;

    //region Constructors
    public Trip() {
        this("");
    }

    public Trip(String name) {
        super(name);
        init();
    }

    public Trip(Trip trip, boolean keepId) {
        super(trip, keepId);
        init();

        mStartDate = trip.getStartDate();
        mEndDate = trip.getEndDate();
        mNotes = trip.getNotes();
    }

    public Trip(UserDefineObject obj) {
        super(obj);
        init();
    }

    public Trip(UserDefineObject obj, boolean keepId) {
        super(obj, keepId);
        init();
    }

    public Trip(JSONObject jsonTrip) throws JSONException {
        super(jsonTrip);
        init();

        mStartDate = new Date(jsonTrip.getLong(Json.START_DATE));
        mEndDate = new Date(jsonTrip.getLong(Json.END_DATE));

        String notes = jsonTrip.getString(Json.NOTES);
        mNotes = notes.isEmpty() ? null : notes;

        // anglers
        JSONArray jsonAnglers = jsonTrip.getJSONArray(Json.ANGLERS);
        mUsedAnglers.setObjects(JsonImporter.parseUserDefineArray(jsonAnglers, new JsonImporter.OnGetObject() {
            @Override
            public UserDefineObject onGetObject(String name) {
                return Logbook.getAngler(UUID.fromString(name));
            }
        }));

        // locations
        JSONArray jsonLocations = jsonTrip.getJSONArray(Json.LOCATIONS);
        mUsedLocations.setObjects(JsonImporter.parseUserDefineArray(jsonLocations, new JsonImporter.OnGetObject() {
            @Override
            public UserDefineObject onGetObject(String name) {
                return Logbook.getLocation(UUID.fromString(name));
            }
        }));

        // catches
        JSONArray jsonCatches = jsonTrip.getJSONArray(Json.CATCHES);
        mUsedCatches.setObjects(JsonImporter.parseUserDefineArray(jsonCatches, new JsonImporter.OnGetObject() {
            @Override
            public UserDefineObject onGetObject(String name) {
                return Logbook.getCatch(UUID.fromString(name));
            }
        }));
    }

    private void init() {
        mStartDate = new Date();
        mEndDate = new Date();

        mUsedAnglers = new UsedUserDefineObject(getId(), UsedAnglerTable.NAME, UsedAnglerTable.Columns.TRIP_ID, UsedAnglerTable.Columns.ANGLER_ID);
        mUsedLocations = new UsedUserDefineObject(getId(), UsedLocationTable.NAME, UsedLocationTable.Columns.TRIP_ID, UsedLocationTable.Columns.LOCATION_ID);
        mUsedCatches = new UsedUserDefineObject(getId(), UsedCatchTable.NAME, UsedCatchTable.Columns.TRIP_ID, UsedCatchTable.Columns.CATCH_ID);
    }
    //endregion

    @Override
    public Date getDate() {
        return getStartDate();
    }

    //region Getters & Setters
    public Date getStartDate() {
        return mStartDate;
    }

    public void setStartDate(Date startDate) {
        mStartDate = startDate;
    }

    public Date getEndDate() {
        return mEndDate;
    }

    public void setEndDate(Date endDate) {
        mEndDate = endDate;
    }

    public String getNotes() {
        return mNotes;
    }

    public void setNotes(String notes) {
        mNotes = notes;
    }

    @Override
    public void setIsSelected(boolean isSelected) {
        super.setIsSelected(isSelected);
        Logbook.editTrip(getId(), this);
    }
    //endregion

    //region Angler Manipulation
    public ArrayList<UserDefineObject> getAnglers() {
        return mUsedAnglers.getObjects(new QueryHelper.UsedQueryCallbacks() {
            @Override
            public UserDefineObject getFromLogbook(UUID id) {
                return Logbook.getAngler(id);
            }
        });
    }

    public void setAnglers(ArrayList<UserDefineObject> anglers) {
        mUsedAnglers.setObjects(anglers);
    }

    public int getAnglersCount() {
        return getAnglers().size();
    }

    public boolean hasAnglers() {
        return getAnglersCount() > 0;
    }
    //endregion

    //region Location Manipulation
    public ArrayList<UserDefineObject> getLocations() {
        return mUsedLocations.getObjects(new QueryHelper.UsedQueryCallbacks() {
            @Override
            public UserDefineObject getFromLogbook(UUID id) {
                return Logbook.getLocation(id);
            }
        });
    }

    public void setLocations(ArrayList<UserDefineObject> locations) {
        mUsedLocations.setObjects(locations);
    }
    //endregion

    //region Catch Manipulation
    public ArrayList<UserDefineObject> getCatches() {
        return mUsedCatches.getObjects(new QueryHelper.UsedQueryCallbacks() {
            @Override
            public UserDefineObject getFromLogbook(UUID id) {
                return Logbook.getCatch(id);
            }
        });
    }

    public void setCatches(ArrayList<UserDefineObject> catches) {
        mUsedCatches.setObjects(catches);
    }

    /**
     * @return Sum of the quantity properties for each of this Trip's catches.
     */
    @Override
    public int getFishCaughtCount() {
        return QueryHelper.queryTripsCatchCount(this);
    }
    //endregion

    /**
     * Loops through all the Trip's catches and creates an array of {@link Bait} objects that were
     * used. The resulting array has unique values.
     *
     * @return An array of {@link Bait} objects used during this trip.
     */
    public ArrayList<UserDefineObject> getBaits() {
        ArrayList<UserDefineObject> result = new ArrayList<>();
        ArrayList<UserDefineObject> catches = getCatches();

        for (UserDefineObject obj : catches) {
            Bait bait = ((Catch) obj).getBait();
            if (bait == null)
                continue;

            boolean add = true;

            // check to see if the current bait already exists in the result
            for (UserDefineObject o : result)
                if (o.getIdAsString().equals(bait.getIdAsString())) {
                    add = false;
                    break;
                }

            if (add)
                result.add(bait);
        }

        return result;
    }

    public String getNotesAsString() {
        return (mNotes != null) ? mNotes : "";
    }

    public String getStartDateAsString(Context context) {
        return Utils.getMediumDisplayDate(mStartDate, context);
    }

    public String getEndDateAsString(Context context) {
        return Utils.getMediumDisplayDate(mEndDate, context);
    }

    public String getDateAsString(Context context) {
        return String.format(context.getString(R.string.date_date_format),
                getStartDateAsString(context), getEndDateAsString(context));
    }

    public String getCatchesAsString(Context context) {
        int count = getFishCaughtCount();
        String catchesStr = count == 1 ? context.getResources().getString(R.string.catch_string) : context.getResources().getString(R.string.drawer_catches);
        return count + " " + catchesStr;
    }

    public String getAnglersAsString() {
        return UserDefineArrays.namesAsString(getAnglers());
    }

    public boolean hasNotes() {
        return mNotes != null && !mNotes.isEmpty();
    }

    public boolean overlapsTrip(Trip trip) {
        return trip.getStartDate().before(mEndDate) && trip.getEndDate().after(mStartDate);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public ContentValues getContentValues() {
        ContentValues values = super.getContentValues();

        values.put(TripTable.Columns.START_DATE, mStartDate.getTime());
        values.put(TripTable.Columns.END_DATE, mEndDate.getTime());

        if (mNotes != null)
            values.put(TripTable.Columns.NOTES, mNotes);

        return values;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Intent getShareIntent(Context context) {
        Intent intent = super.getShareIntent(context);

        String text = "Trip to " + UserDefineArrays.namesAsString(getLocations()) + " caught " + getFishCaughtCount() + " fish. ";
        intent.putExtra(Intent.EXTRA_TEXT, text + intent.getStringExtra(Intent.EXTRA_TEXT));

        return intent;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public JSONObject toJson() throws JSONException {
        JSONObject json = super.toJson();

        json.put(Json.START_DATE, mStartDate.getTime());
        json.put(Json.END_DATE, mEndDate.getTime());
        json.put(Json.NOTES, getNotesAsString());
        json.put(Json.CATCHES, JsonExporter.getIdJsonArray(getCatches()));
        json.put(Json.LOCATIONS, JsonExporter.getIdJsonArray(getLocations()));
        json.put(Json.ANGLERS, JsonExporter.getIdJsonArray(getAnglers()));

        return json;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toKeywordsString(Context context) {
        StringBuilder builder = new StringBuilder(super.toKeywordsString(context));

        appendToBuilder(builder, Utils.getLongDisplayDate(mStartDate, context));
        appendToBuilder(builder, Utils.getLongDisplayDate(mEndDate, context));
        appendToBuilder(builder, mNotes);

        builder.append(UserDefineArrays.keywordsAsString(context, getAnglers()));
        builder.append(UserDefineArrays.keywordsAsString(context, getCatches()));
        builder.append(UserDefineArrays.keywordsAsString(context, getLocations()));

        return builder.toString();
    }

    /**
     * {@inheritDoc}
     *
     * Used for deleting trips. This method will remove any external ties to the database. For
     * example, removing used locations and catches. It removes the trip-to-object pairs in the
     * "Used *" tables.
     */
    @Override
    public void removeDatabaseProperties() {
        super.removeDatabaseProperties();

        mUsedCatches.deleteObjects();
        mUsedLocations.deleteObjects();
        mUsedAnglers.deleteObjects();
    }
}

package com.cohenadair.anglerslog.trips;

import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;

import com.cohenadair.anglerslog.R;
import com.cohenadair.anglerslog.fragments.ManageContentFragment;
import com.cohenadair.anglerslog.fragments.ManagePrimitiveFragment;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.user_defines.Catch;
import com.cohenadair.anglerslog.model.user_defines.Trip;
import com.cohenadair.anglerslog.model.user_defines.UserDefineObject;
import com.cohenadair.anglerslog.model.utilities.UserDefineArrays;
import com.cohenadair.anglerslog.utilities.AlertUtils;
import com.cohenadair.anglerslog.utilities.LayoutSpecManager;
import com.cohenadair.anglerslog.utilities.PrimitiveSpecManager;
import com.cohenadair.anglerslog.utilities.ViewUtils;
import com.cohenadair.anglerslog.views.InputButtonView;
import com.cohenadair.anglerslog.views.InputTextView;

import java.util.ArrayList;
import java.util.Date;
import java.util.UUID;

/**
 * The ManageTripFragment is used to add and edit trips.
 * @author Cohen Adair
 */
public class ManageTripFragment extends ManageContentFragment {

    private InputTextView mNameView;
    private InputTextView mNotesView;
    private InputButtonView mStartDateView;
    private InputButtonView mEndDateView;
    private InputButtonView mCatchesView;
    private InputButtonView mLocationsView;
    private InputButtonView mAnglersView;

    /**
     * Used so there is no database interaction until the user saves their changes.
     */
    private ArrayList<UUID> mSelectedAnglersIds;
    private ArrayList<UUID> mSelectedCatchesIds;
    private ArrayList<UUID> mSelectedLocationsIds;

    private ArrayList<View> mCatchesViews;
    private ArrayList<View> mLocationsViews;

    private boolean mDateChanged = false;

    public ManageTripFragment() {
        // Required empty public constructor
    }

    private Trip getNewTrip() {
        return (Trip)getNewObject();
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_manage_trip, container, false);

        initNameView(view);
        initNotesView(view);
        initStartDateView(view);
        initEndDateView(view);
        initCatchesView(view);
        initLocationsView(view);
        initAnglersView(view);

        initSelectedAnglers();
        initSelectedCatches();
        initSelectedLocations();

        return view;
    }

    @Override
    public void onResume() {
        super.onResume();
        initInputListeners(); // this MUST be called in onResume()
    }

    @Override
    public ManageObjectSpec getManageObjectSpec() {
        return new ManageObjectSpec(R.string.error_trip, R.string.success_trip, R.string.error_trip_edit, R.string.success_trip_edit, new ManageInterface() {
            @Override
            public boolean onEdit() {
                return Logbook.editTrip(getEditingId(), getNewTrip());
            }

            @Override
            public boolean onAdd() {
                return Logbook.addTrip(getNewTrip());
            }
        });
    }

    @Override
    public void initSubclassObject() {
        initObject(new InitializeInterface() {
            @Override
            public UserDefineObject onGetOldObject() {
                return Logbook.getTrip(getEditingId());
            }

            @Override
            public UserDefineObject onGetNewEditObject(UserDefineObject oldObject) {
                Trip trip = new Trip((Trip) oldObject, true);
                mSelectedLocationsIds = UserDefineArrays.asIdArray(trip.getLocations());
                mSelectedAnglersIds = UserDefineArrays.asIdArray(trip.getAnglers());
                mSelectedCatchesIds = UserDefineArrays.asIdArray(trip.getCatches());
                return trip;
            }

            @Override
            public UserDefineObject onGetNewBlankObject() {
                return new Trip();
            }
        });
    }

    @Override
    public boolean verifyUserInput() {
        // make sure the new trip doesn't overlap any existing trips
        if ((mDateChanged || !isEditing()) && Logbook.tripExists(getNewTrip())) {
            AlertUtils.showError(getActivity(), R.string.error_trip_date);
            return false;
        }

        // start and end dates are set after the DatePickerFragment is closed
        // input properties are set in a onTextChanged listener

        // update properties that interact directly with the database
        getNewTrip().setAnglers(getSelectedAnglers());
        getNewTrip().setCatches(getSelectedCatches());
        getNewTrip().setLocations(getSelectedLocations());

        return true;
    }

    //region View Updating

    @Override
    protected void validateNewObject() {
        Trip newTrip = getNewTrip();

        newTrip.setAnglers(UserDefineArrays.getValidObjects(newTrip.getAnglers(), new UserDefineArrays.OnConvertInterface() {
            @Override
            public UserDefineObject onGetObject(String idStr) {
                return Logbook.getAngler(UUID.fromString(idStr));
            }
        }));
    }

    @Override
    protected void updateViews() {
        mNameView.setInputText(getNewTrip().getNameAsString());
        mStartDateView.setPrimaryButtonText(getNewTrip().getStartDateAsString(getContext()));
        mEndDateView.setPrimaryButtonText(getNewTrip().getEndDateAsString(getContext()));
        mAnglersView.setPrimaryButtonText(UserDefineArrays.namesAsString(getSelectedAnglers()));
        mNotesView.setInputText(getNewTrip().getNotesAsString());

        updateCatchesViews();
        updateLocationsViews();
    }

    private void updateCatchesViews() {
        removeViews(mCatchesViews);
        mCatchesView.setPrimaryButtonText(UserDefineArrays.propertiesAsString(getSelectedCatches(), new UserDefineArrays.OnGetPropertyInterface() {
            @Override
            public String onGetProperty(UserDefineObject object) {
                return ((Catch) object).getSpeciesAsString();
            }
        }));
    }

    private void updateLocationsViews() {
        removeViews(mLocationsViews);
        mLocationsView.setPrimaryButtonText(UserDefineArrays.namesAsString(getSelectedLocations()));
    }

    /**
     * Removes the given View objects from their parent.
     * @param views The View objects to remove.
     */
    private void removeViews(ArrayList<View> views) {
        for (View view : views) {
            ViewGroup parent = ((ViewGroup)view.getParent());
            if (parent != null)
                parent.removeView(view);
        }
    }
    //endregion

    //region View Initializing
    public void initNameView(View view) {
        mNameView = (InputTextView)view.findViewById(R.id.name_view);
    }

    public void initNotesView(View view) {
        mNotesView = (InputTextView)view.findViewById(R.id.notes_view);
    }

    public void initAnglersView(View view) {
        final ManagePrimitiveFragment.OnDismissInterface onDismissInterface = getDismissInterface(new PrimitiveDismissListener() {
            @Override
            public void onDismissWithSelection(ArrayList<UUID> selectedIds) {
                mSelectedAnglersIds = selectedIds;
                mAnglersView.setPrimaryButtonText(UserDefineArrays.namesAsString(getSelectedAnglers()));
            }
        });

        mAnglersView = (InputButtonView)view.findViewById(R.id.anglers_view);
        mAnglersView.setOnClickPrimaryButton(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                showPrimitiveDialog(PrimitiveSpecManager.ANGLERS, true, mSelectedAnglersIds, onDismissInterface);
            }
        });
    }

    public void initStartDateView(View view) {
        mStartDateView = (InputButtonView)view.findViewById(R.id.start_date_view);
        mStartDateView.setOnClickPrimaryButton(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                showDatePickerFragment(getNewTrip().getStartDate(), new DateTimePickerInterface() {
                    @Override
                    public void onFinish(Date date) {
                        if (date.after(getNewTrip().getEndDate())) {
                            AlertUtils.showError(getActivity(), R.string.error_trip_date_start);
                            return;
                        }

                        getNewTrip().setStartDate(date);
                        mStartDateView.setPrimaryButtonText(
                                getNewTrip().getStartDateAsString(getContext()));
                        mDateChanged = isEditing();
                    }
                });
            }
        });
    }

    public void initEndDateView(View view) {
        mEndDateView = (InputButtonView)view.findViewById(R.id.end_date_view);
        mEndDateView.setOnClickPrimaryButton(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                showDatePickerFragment(getNewTrip().getEndDate(), new DateTimePickerInterface() {
                    @Override
                    public void onFinish(Date date) {
                        if (date.before(getNewTrip().getStartDate())) {
                            AlertUtils.showError(getActivity(), R.string.error_trip_date_end);
                            return;
                        }

                        getNewTrip().setEndDate(date);
                        mEndDateView.setPrimaryButtonText(
                                getNewTrip().getEndDateAsString(getContext()));
                        mDateChanged = isEditing();
                    }
                });
            }
        });
    }

    public void initCatchesView(View view) {
        mCatchesView = (InputButtonView)view.findViewById(R.id.catches_view);
        mCatchesView.setOnClickPrimaryButton(new View.OnClickListener() {
            @Override
